ледних.КВБордеро, 0) + ЕСТЬNULL(Renault_ФинансовыеПолитикиСтраховыхКомпанийСрезПоследних.КВДВОУ, 0) - ЕСТЬNULL(ТаблицаБСО.СтраховойПолис.ПроцентСкидкиЗасчетКВ, 0)) / 100 КАК ВознаграждениеАгентаСумма, ЕСТЬNULL(ТаблицаБСО.Сумма, 0) - ЕСТЬNULL(ТаблицаБСО.Сумма, 0) * (ЕСТЬNULL(Renault_ФинансовыеПолитикиСтраховыхКомпанийСрезПоследних.КВБордеро, 0) + ЕСТЬNULL(Renault_ФинансовыеПолитикиСтраховыхКомпанийСрезПоследних.КВДВОУ, 0) - ЕСТЬNULL(ТаблицаБСО.СтраховойПолис.ПроцентСкидкиЗасчетКВ, 0)) / 100 КАК ПремияСтраховщику, МестонахождениеБСО.Статус, МестонахождениеБСО.Местонахождение ИЗ ТаблицаБСО КАК ТаблицаБСО ЛЕВОЕ СОЕДИНЕНИЕ РегистрСведений.Renault_ФинансовыеПолитикиСтраховыхКомпаний.СрезПоследних(КОНЕЦПЕРИОДА(&КонецПериода, ДЕНЬ) {(&КонецПериода)}, ) КАК Renault_ФинансовыеПолитикиСтраховыхКомпанийСрезПоследних ПО ТаблицаБСО.СтраховаяКомпания = Renault_ФинансовыеПолитикиСтраховыхКомпанийСрезПоследних.СтраховаяКомпания И ТаблицаБСО.ВидСтрахования = Renault_ФинансовыеПолитикиСтраховыхКомпанийСрезПоследних.ВидСтрахования ЛЕВОЕ СОЕДИНЕНИЕ СтраховыеРиски КАК СтраховыеРиски ПО ТаблицаБСО.СтраховойПолис = СтраховыеРиски.Ссылка ЛЕВОЕ СОЕДИНЕНИЕ МестонахождениеБСО КАК МестонахождениеБСО ПО ТаблицаБСО.НомерБСО = МестонахождениеБСО.НомерБСО И ТаблицаБСО.СерияБСО = МестонахождениеБСО.СерияБСО И ТаблицаБСО.СтраховаяКомпания = МестонахождениеБСО.СтраховаяКомпания И ТаблицаБСО.ТипБСО = МестонахождениеБСО.ТипБСО
